package server

import "net/http"

const subtitleOnboardingHTML = `<!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0b0d0b"><title>Choose your subtitle plan · Kinosail Subtitles</title><script src="/static/theme.js?v=electric-1"></script><link rel="stylesheet" href="/static/app.css?v=electric-1"></head><body class="settings-page onboarding-page subtitle-onboarding"><a class="skip" href="#main">Skip to content</a><main id="main" class="settings-shell onboarding-shell"><nav class="wizard-progress" aria-label="Setup progress"><a class="is-done" href="/account"><span>01</span>Owner account</a><a class="is-current" href="/onboarding/connection" aria-current="step"><span>02</span>Subtitle plan</a></nav><header class="settings-intro"><span class="eyebrow">Step 2 of 2 · Subtitle plan</span><h1>Connect a provider. Let Kinosail handle the rest.</h1><p>Your language, folders, and schedule are already set. The defaults handle everyday subtitle maintenance; adjust them only when your household needs something different.</p></header><div class="subtitle-onboarding-layout"><div class="subtitle-onboarding-steps">
<section id="providers"><header><span>01</span><div><h2>Connect a subtitle provider</h2><p>One provider is enough to start. Save its credentials, restart when prompted, and Kinosail will find missing subtitles automatically.</p></div></header><div class="subtitle-provider-setup">{{range .ProviderSetup}}<article><header><h3>{{.Name}}</h3><span class="subtitle-readiness-state {{if .Configured}}ready{{end}}">{{if .Configured}}Configured{{else}}Not configured{{end}}</span></header><p>{{.Instructions}}</p><p class="subtitle-provider-links"><a class="mode" href="{{.AccountURL}}" target="_blank" rel="noopener noreferrer">Create {{.Name}} account</a> <a class="mode" href="{{.DocsURL}}" target="_blank" rel="noopener noreferrer">Key instructions</a></p><a class="button" href="{{.SettingsURL}}">Enter key in Kinosail</a></article>{{end}}</div><p class="subtitle-provider-privacy">Provider searches receive media identity and language metadata, not media bytes. Embedded and existing sidecar subtitles stay local.</p></section><section><h2>Ready-to-use defaults</h2><p>Use {{.Language}} {{.Preference}} subtitles, prefer embedded text, and check for missing files every 15 minutes. Preserve original downloads, back up replacements, and leave uncertain timing unchanged.</p><p>Optional OCR and transcription create local drafts for review. They never replace subtitles automatically.</p></section><details><summary>Review language, media scope, and schedule</summary><section id="language"><header><span>01</span><div><h2>Choose the primary subtitle language</h2><p>Embedded text comes first. Select the primary language and preferred subtitle role.</p></div></header><form action="/onboarding/subtitles/language" method="post"><fieldset {{if .LanguageManaged}}disabled aria-disabled="true"{{end}}><label>Primary language<select name="language" aria-describedby="language-help" required>{{range .AllLanguages}}<option value="{{.Tag}}" {{if .Selected}}selected{{end}}>{{.Name}} ({{.Tag}})</option>{{end}}</select></label><p id="language-help">Common languages appear first. You can choose from the complete catalog.</p><label>Preferred subtitle role<select name="preference"><option value="standard" {{if eq .Preference "standard"}}selected{{end}}>Standard dialogue</option><option value="sdh" {{if eq .Preference "sdh"}}selected{{end}}>SDH and captions</option></select></label><button class="quiet">Save plan</button></fieldset></form>{{if .LanguageManaged}}<p class="status">Managed by deployment configuration.</p>{{end}}</section><section id="libraries"><header><span>02</span><div><h2>Choose where to save subtitle files</h2><p>Kinosail checks subtitle files before saving them beside your videos. The Server needs permission to write to these folders.</p></div></header><p>Media mount: <code>{{.MediaRoot}}</code></p><div class="subtitle-library-list" aria-label="Configured media folders">{{range .Libraries}}{{if or (eq . ".") $.LibrariesManaged}}<div class="subtitle-library-scope"><code>{{if eq . "."}}Entire media mount{{else}}{{.}}{{end}}</code>{{if eq . "."}}<span class="status">Active</span>{{end}}</div>{{else}}<form action="/onboarding/subtitles/libraries/remove" method="post"><fieldset><code>{{.}}</code><button class="quiet" name="path" value="{{.}}" aria-label="Remove {{.}}">Remove</button></fieldset></form>{{end}}{{end}}</div><form action="/onboarding/subtitles/libraries" method="post"><fieldset {{if .LibrariesManaged}}disabled aria-disabled="true"{{end}}><label>Folder inside media mount<input name="path" placeholder="Movies" maxlength="4096" required></label>{{if and (eq (len .Libraries) 1) (eq (index .Libraries 0) ".")}}<p>Once you add a folder, Kinosail will use only the folders you select.</p>{{end}}<button class="quiet">Add folder</button></fieldset></form>{{if .LibrariesManaged}}<p class="status">Managed by deployment configuration.</p>{{end}}</section><section id="automation"><header><span>03</span><div><h2>Choose a scan schedule</h2><p>Kinosail detects files when copying finishes. Scheduled scans catch changes it may have missed.</p></div></header><form action="/onboarding/subtitles/scans" method="post"><fieldset {{if .ScansManaged}}disabled aria-disabled="true"{{end}}><label>Safety scan<select name="frequency"><option value="default" {{if eq .Frequency "default"}}selected{{end}}>Server default</option><option value="5m" {{if eq .Frequency "5m"}}selected{{end}}>Every 5 minutes</option><option value="15m" {{if eq .Frequency "15m"}}selected{{end}}>Every 15 minutes</option><option value="1h" {{if eq .Frequency "1h"}}selected{{end}}>Every hour</option><option value="off" {{if eq .Frequency "off"}}selected{{end}}>Only filesystem events</option></select></label><button class="quiet">Save schedule</button></fieldset></form>{{if .ScansManaged}}<p class="status">Managed by deployment configuration.</p>{{end}}</section></details>
 </div><aside class="subtitle-readiness" aria-labelledby="readiness-title"><span class="eyebrow">Readiness check</span><h2 id="readiness-title">Your subtitle plan</h2><dl><div><dt>Language</dt><dd><strong>{{.Language}}</strong></dd></div><div><dt>Media scope</dt><dd>{{if and (eq (len .Libraries) 1) (eq (index .Libraries 0) ".")}}Entire media mount{{else}}{{len .Libraries}} selected {{if eq (len .Libraries) 1}}folder{{else}}folders{{end}}{{end}}</dd></div><div><dt>Provider</dt><dd><span class="subtitle-readiness-state {{if .ProviderConfigured}}ready{{end}}">{{if .ProviderConfigured}}Ready{{else}}Not configured{{end}}</span></dd></div><div><dt>Safety scan</dt><dd>{{if eq .Frequency "off"}}Filesystem events only{{else if eq .Frequency "default"}}Server default{{else}}{{.Frequency}}{{end}}</dd></div></dl>{{if .ProviderConfigured}}<p>Provider credentials are configured. Kinosail still uses local sidecars and embedded text first.</p>{{else}}<p>Set up one provider to let Kinosail find missing files. Embedded and existing sidecar subtitles work without one.</p><p><a class="mode" href="/settings#provider">Configure a provider</a></p>{{end}}<p class="subtitle-readiness-note">Provider requests do not include your media files. You can review saved subtitle changes in each file’s installation history.</p></aside></div><footer class="subtitle-onboarding-actions"><a class="mode" href="/settings">Review all settings</a><div><span>You can change these choices in Settings.</span><a class="button" href="/onboarding/finish">Finish and open overview</a></div></footer></main></body></html>`

var subtitleOnboardingView = newLocalizedTemplate("subtitle-onboarding", updateChoicePage(subtitleOnboardingHTML))

func registerSubtitleOnboarding(mux *http.ServeMux, auth *authentication, settings *settingsStore, provider *subtitleProvider) {
	mux.Handle("GET /onboarding", auth.owner(http.RedirectHandler("/onboarding/connection", http.StatusSeeOther)))
	mux.Handle("GET /onboarding/connection", auth.owner(showSubtitleOnboarding(settings, provider)))
}

func registerSubtitleOnboardingActions(mux *http.ServeMux, auth *authentication, settings *settingsStore, index *libraryIndex) {
	mux.Handle("POST /onboarding/subtitles/language", auth.owner(savePrimarySubtitleLanguage(settings, "/onboarding/connection#language")))
	mux.Handle("POST /onboarding/subtitles/libraries", auth.owner(changeLibrary(settings, index, settings.add, "/onboarding/connection#libraries")))
	mux.Handle("POST /onboarding/subtitles/libraries/remove", auth.owner(changeLibrary(settings, index, settings.remove, "/onboarding/connection#libraries")))
	mux.Handle("POST /onboarding/subtitles/scans", auth.owner(saveScanFrequency(settings, index, "/onboarding/connection#automation")))
}

func showSubtitleOnboarding(settings *settingsStore, provider *subtitleProvider) http.HandlerFunc {
	return func(writer http.ResponseWriter, request *http.Request) {
		writer.Header().Set("Content-Type", "text/html; charset=utf-8")
		if err := subtitleOnboardingView.Execute(writer, request, subtitleSettingsPageData(settings, provider, nil)); err != nil {
			localizedError(writer, request, "subtitle setup is unavailable", http.StatusInternalServerError)
		}
	}
}
